CREATE OR REPLACE FUNCTION planner_private.pending_daily_worker(action text, batch_day date, target uuid DEFAULT NULL::uuid, lease uuid DEFAULT NULL::uuid, payload jsonb DEFAULT NULL::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$ declare j planner_private.daily_pending_jobs%rowtype;p planner_private.pending_visitors%rowtype;n uuid;documents jsonb;credential text; begin if auth.role() is distinct from 'service_role' then raise exception 'Server role required' using errcode='42501'; end if; if action='claim' then update planner_private.daily_pending_jobs set status='failed',error_code='attempt_limit' where day=batch_day and status='running' and lease_until<=now() and attempts>=3; select * into j from planner_private.daily_pending_jobs where day=batch_day and attempts<3 and ((status='pending' and available_at<=now()) or (status='running' and lease_until<=now())) order by owner_id for update skip locked limit 1; if not found then return jsonb_build_object('job',null)||planner_private.daily_summary(batch_day); end if; select * into p from planner_private.pending_visitors where id=j.owner_id for share; if p.status='disabled' or md5(p.envelope) is distinct from j.fingerprint then update planner_private.daily_pending_jobs set status='ineligible',error_code='binding_changed' where day=batch_day and owner_id=j.owner_id; return jsonb_build_object('job',null)||planner_private.daily_summary(batch_day); end if; n:=gen_random_uuid();update planner_private.daily_pending_jobs set status='running',attempts=attempts+1,token=n,lease_until=now()+interval '25 minutes' where day=batch_day and owner_id=j.owner_id; return jsonb_build_object('job',jsonb_build_object('owner',p.id,'envelope',p.envelope,'accountLabel',p.account_label,'lease',n,'day',batch_day,'kind','pending_google','linkedTo',p.linked_to)); end if; if action not in ('publish','fail') then raise exception 'Invalid pending action'; end if; select * into j from planner_private.daily_pending_jobs where day=batch_day and owner_id=target for update; if not found or j.status<>'running' or j.token is distinct from lease or j.lease_until<=now() then raise exception 'Job lease lost' using errcode='40001'; end if; if action='fail' then update planner_private.daily_pending_jobs set status=case when attempts>=3 then 'failed' else 'pending' end,available_at=now()+interval '60 seconds',token=null,lease_until=null,error_code='export_failed' where day=batch_day and owner_id=target; return planner_private.daily_summary(batch_day); end if; select * into p from planner_private.pending_visitors where id=target for update; if p.status='disabled' or md5(p.envelope) is distinct from j.fingerprint then raise exception 'Binding changed' using errcode='40001'; end if; documents:=case when jsonb_typeof(payload)='object' then payload->'documents' else payload end; credential:=case when jsonb_typeof(payload)='object' then payload->>'credential' else null end; perform planner_private.validate_daily_snapshot(documents); if p.linked_to is not null then perform 1 from public.planner_members m join auth.users u on u.id=m.id where m.id=p.linked_to and m.active and u.email_confirmed_at is not null and u.raw_app_meta_data->>'provider'='google' for share of m; if not found then raise exception 'Linked member disabled' using errcode='42501'; end if; perform 1 from public.planner_credentials c where c.owner_id=p.linked_to for update; if exists(select 1 from public.planner_credentials where owner_id=p.linked_to and nullif(btrim(account_label),'') is not null and lower(btrim(account_label))<>lower(btrim(p.account_label))) then raise exception 'Linked company account changed' using errcode='40001'; end if; if credential is null or length(credential)>20000 or (credential::jsonb)->>'version'<>'1' then raise exception 'Re-encrypted binding required'; end if; insert into public.planner_credentials(owner_id,envelope,account_label,data) values(p.linked_to,credential,p.account_label,jsonb_build_object('version',1,'verified',true,'verifiedAt',now())) on conflict(owner_id) do update set envelope=excluded.envelope,account_label=excluded.account_label,data=excluded.data,updated_at=now() where nullif(btrim(public.planner_credentials.account_label),'') is null or (lower(btrim(public.planner_credentials.account_label))=lower(btrim(excluded.account_label)) and coalesce(public.planner_credentials.data->>'verified','false')<>'true'); if not exists(select 1 from public.planner_credentials c where c.owner_id=p.linked_to and lower(btrim(c.account_label))=lower(btrim(p.account_label)) and c.data->>'verified'='true') then raise exception 'Linked company account changed' using errcode='40001';end if; perform planner_private.apply_daily_snapshot(p.linked_to,documents); end if; update planner_private.pending_visitors set last_snapshot=documents,last_source_at=now() where id=target; update planner_private.daily_pending_jobs set status='done',finished_at=now(),token=null,lease_until=null,error_code=null where day=batch_day and owner_id=target; return planner_private.daily_summary(batch_day); end; $function$;